import math

def get_divisors(n):
    divs = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
    divs.sort()
    return divs

def count_divisors(n):
    return len(get_divisors(n))

results = []
for n in range(1, 100):
    if count_divisors(n) >= 5:
        divs = get_divisors(n)

        # We need at least 5 divisors for d5 to exist
        if len(divs) >= 5:
            # Smallest divisor is d1 = 1.
            # Second smallest is d2 = a
            a = divs[1]
            # Third smallest is d3 = b
            b = divs[2]
            # Fifth smallest is d5 = c
            c = divs[4]

            # Check the condition: ab + ac + bc = n
            check = a * b + a * c + b * c

            if check == n:
                # Store results
                results.append({
                    'n': n,
                    'tau(n)': count_divisors(n),
                    'a': a,
                    'b': b,
                    'c': c,
                    'holds': True
                })

# Print the results clearly
print("--- Found solutions ---")
for res in results:
    print(f"n={res['n']}, tau(n)={res['tau(n)']}, a={res['a']}, b={res['b']}, c={res['c']}, holds=True")

print("\n--- Summary ---")
if results:
    print("All solutions found:")
    for res in results:
        print(f"n={res['n']}, tau(n)={res['tau(n)']}")
else:
    print("No solutions found for n < 100.")

import math

def count_divisors(n):
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            count += 1
            if i * i != n:
                count += 1
    return count

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

candidates = {
    36: (2, 3, 6), # Checked already, but good for consistency
    56: (2, 4, 8), # Checked already
    135: (3, 5, 15),
    231: (3, 7, 21),
    351: (3, 9, 27)
}

results = {}
for n, (a, b, c) in candidates.items():
    divs = get_divisors(n)
    tau = count_divisors(n)

    # Check if the given a, b, c match the actual d2, d3, d5
    if len(divs) >= 5:
        d2 = divs[1]
        d3 = divs[2]
        d5 = divs[4]

        is_feasible = (a == d2) and (b == d3) and (c == d5)

        results[n] = {
            "tau": tau,
            "divisors": divs,
            "feasible": is_feasible
        }

print("--- Results ---")
for n, data in results.items():
    print(f"N={n}: tau={data['tau']}, Feasible={data['feasible']}, Divs={data['divisors']}")
